n("יון", "יון הוא שם בינלאומי, צורה של יוחנן, שם עברי שפירושו ה׳ חנן. ברומנית יון הוא שם נפוץ מאוד, ובוולשית מוכרת הצורה איואן. בעברית השם נשמע קרוב ליונה וליוני. השם ניתן לבנים, והוא נדיר בארץ.", ["יוני", "יונה"])
n("ארנית", "ארנית הוא שם עברי מהמילה אורן בכתיב חסר, עץ מחטני ירוק שגדל בהרים. השם קרוב לשמות אורנה ואורנית, והוא היה מוכר בארץ בשנות החמישים והשישים. השם ניתן לבנות, והוא נדיר היום.", ["אורנית", "אורנה"])
n("יכין", "יכין הוא שם עברי מהשורש כ־ו־ן, ופירושו יבסס ויחזק. בספר מלכים יכין ובועז הם שני העמודים שעמדו בפתח המקדש של שלמה. יכין היה גם אחד מבני שמעון. השם ניתן גם לבנים וגם לבנות, והוא נדיר.", ["בועז"])
n("ריצארד", "ריצארד הוא כתיב של ריצ׳רד, שם בינלאומי ממקור גרמני שפירושו שליט חזק. בכתיב הזה השם קרוב להגייה הצרפתית, רישאר. השם ניתן לבנים, והוא נדיר מאוד בארץ.", ["ריצ'רד"])
n("עמל", "עמל הוא שם עברי מהמילה עמל, עבודה קשה ומאמץ. השם מבטא ערך של עבודה ושל התמדה. השם ניתן לבנות, והוא נדיר. קרוב אליו בצליל השם עמליה, ובשפות אחרות הוא נשמע גם כמו אמל, תקווה.", ["עמליה"])
n("דובב", "דובב הוא שם עברי מהמילה דובב, מי שמניע לדבר. בשיר השירים נאמר דובב שפתי ישנים, על יין טוב שמעורר את הישנים לדבר. השם ניתן לבנים, והוא נדיר מאוד, אבל נשמע עתיק ומוזיקלי.", [])
n("מנגיסטו", "מנגיסטו הוא שם באמהרית, השפה של אתיופיה, ופירושו שלטון או ממלכה. השם נפוץ באתיופיה, והוא הגיע לארץ עם העלייה של יהודי אתיופיה. השם ניתן לבנים, והוא נדיר בארץ.", [])
n("גת", "גת היא המקום שבו דורכים ענבים כדי להוציא מהם יין. גת הייתה גם אחת מחמש ערי הפלשתים, ובארץ יש היום קיבוץ גת ועיר קריית גת. השם ניתן לבנות, והוא נדיר. קרובים אליו השמות גתית וגיתית.", ["גתית", "גיתית"])
n("נדר", "נדר הוא שם עברי מהמילה נדר, הבטחה חגיגית לעשות דבר מסוים. במסורת נדר הוא דבר רציני מאוד, שצריך לקיים. השם ניתן לבנים, והוא נדיר. בצליל הוא קרוב לשם נדיר.", ["נדיר"])
n("פוריה", "פוריה הוא שם עברי מהמילה פריון, שפע ופירות. פוריה היא גם שם של יישוב ליד טבריה, מעל הכנרת, ושם של בית חולים מוכר. השם ניתן לבנות, והוא נדיר. קרובים אליו השמות פורת ופריאל.", ["פורת", "פריאל"])
n("טרויה", "טרויה היא עיר עתיקה בצפון מערב אסיה הקטנה, שהמלחמה עליה מתוארת באיליאדה של הומרוס. בשפות אחרות השם נשמע גם כמו טרוי, שם אנגלי. השם ניתן לבנות, והוא נדיר מאוד בארץ.", [])
n("יהלומית", "יהלומית הוא שם עברי מהמילה יהלום, האבן היקרה והקשה ביותר. השם נשמע מנצנץ ויקר. השם ניתן לבנות, והוא נדיר. קרוב אליו השם יהלום, שניתן לבנים.", ["יהלום"])
n("רוויה", "רוויה הוא שם עברי מהמילה רוויה, מלאה ושופעת, כמו אדמה שקיבלה מספיק גשם. השם קרוב לשמות רוית ורווית. השם ניתן לבנות, והוא נדיר. יש בו תחושה של שפע ושל טוב.", ["רוית", "רווית"])
n("ווביט", "ווביט הוא שם באמהרית, השפה של אתיופיה, ופירושו יפה. השם הגיע לארץ עם העלייה של יהודי אתיופיה, והוא ניתן לבנות. הוא נדיר, והצליל שלו רך ומיוחד.", [])
n("כנען", "כנען הוא השם הקדום של ארץ ישראל, לפני שבני ישראל התיישבו בה. השם קשור כנראה למילה כנע, נמוך. השם ניתן גם לבנים וגם לבנות, והוא נדיר. הוא נשמע עתיק וקשור לארץ.", [])
n("יראל", "יראל הוא שם עברי שבנוי מהמילים ירא ואל, ופירושו מי שירא את אלוהים. השם קרוב לשמות כמו יראת ויורית. השם ניתן לבנים, והוא נדיר. יראל הוא גם שם של כמה מקומות בארץ.", ["יראת"])
n("גורן", "גורן היא משטח פתוח שבו דשים את התבואה כדי להפריד את הגרעינים מהקש. השם עברי, והוא מביא תמונה של קציר ושל שפע. גורן היא גם שם של מושב בגליל. השם ניתן גם לבנים וגם לבנות, והוא נדיר.", ["גרנית"])
n("נואית", "נואית הוא שם עברי חדש, וכנראה הוא בא מהמילה נוי, יופי. השם קרוב לשמות כמו נאוה ונאית. השם ניתן לבנות, והוא נדיר. הצליל שלו רך ועדין, והוא נשמע מודרני.", ["נאוה", "נאית"])
n("פרידי", "פרידי היא צורת חיבה של פרידה, שם ביידיש ובגרמנית שקשור למילה פרייד, שמחה, או למילה פרידה, שלום. השם ניתן לבנות, והוא נפוץ בעיקר בקהילות חרדיות. קרובים אליו השמות פרידה ופריידי.", ["פרידה", "פריידי"])
n("שיא", "שיא הוא שם עברי מהמילה שיא, הנקודה הגבוהה ביותר. השם מבטא הצלחה וגובה. השם ניתן גם לבנים וגם לבנות, והוא נדיר. קרוב אליו בצליל השם שי, מתנה.", ["שי"])
n("גפנית", "גפנית הוא שם עברי מהמילה גפן, הצמח שגדלים עליו ענבים. הגפן היא אחד משבעת המינים, וסמל של שפע. השם ניתן לבנות, והוא נדיר. קרובים אליו השמות גפן וגפנה.", ["גפן"])
n("יובב", "יובב הוא שם מקראי. בספר בראשית יובב בן זרח הוא אחד המלכים הקדומים של אדום. השם נשמע עתיק ומיוחד, עם צליל חוזר. השם ניתן לבנים, והוא נדיר מאוד.", [])
n("אליעוז", "אליעוז הוא שם עברי שבנוי מהמילים אלי ועוז, ופירושו האל שלי הוא כוח. מאותה מילה באים גם השמות עוז ועוזיאל. השם ניתן לבנים, והוא נדיר. קרוב אליו מאוד השם אליעז.", ["אליעז", "עוז"])
n("מרית", "מרית הוא שם עברי חדש, וכנראה הוא צורה של מרים. השם קצר ורך, והוא ניתן לבנות. הוא נדיר, וקרובים אליו השמות מירית ומירה. השם מרים הוא שם של הנביאה, אחותם של משה ואהרן.", ["מירית", "מרים"])
n("רצון", "רצון הוא שם עברי מהמילה רצון, משאלה וחסד, וגם קבלה טובה. במסורת עת רצון היא שעה טובה לתפילה. השם ניתן לבנים, והוא נדיר. הוא נשמע עתיק ומלא תקווה.", [])
n("אושיק", "אושיק הוא צורת חיבה של אושר, ובקהילות של יוצאי ברית המועצות גם של שמות כמו יהושע. השם נשמע חם ומשפחתי. השם ניתן לבנים, והוא נדיר.", ["אושר"])
n("צלילה", "צלילה הוא שם עברי מהמילה צליל, קול נעים. השם קרוב לשמות צליל וצילה. השם ניתן לבנות, והוא נדיר. בעברית צלילה היא גם ירידה למים, ולכן יש בשם גם תמונה של ים.", ["צליל", "צילה"])
n("שיריי", "שיריי הוא שם עברי חדש שפירושו השירים שלי. השם קרוב לשמות שיר ושירי. השם ניתן לבנות, והוא נדיר. הוא נשמע מוזיקלי ושמח, ויש בו גם צליל של המילה שרי.", ["שירי", "שיר"])
n("ולדי", "ולדי היא צורת חיבה של ולדימיר, שם סלאבי שבנוי מהמילים שלטון ועולם. השם נפוץ בקרב דוברי רוסית, והוא הגיע לארץ עם העלייה. השם ניתן לבנים, והוא נדיר.", ["ולדימיר"])
n("אבישר", "אבישר הוא שם עברי חדש שבנוי מהמילים אבי ושר, ופירושו אבי הוא שר. השם קרוב לשמות כמו אבישי ואבינעם. השם ניתן לבנים, והוא נדיר. אבישר הוא גם שם משפחה מוכר בארץ.", ["אבישי"])
n("עוגן", "עוגן הוא שם עברי מהמילה עוגן, הכלי הכבד שמחזיק ספינה במקום. השם מבטא יציבות ובטחון. עוגן הוא גם שם של קיבוץ בשרון. השם ניתן גם לבנים וגם לבנות, והוא נדיר.", [])
n("קטלינה", "קטלינה היא צורה ספרדית ואיטלקית של קתרין, שם ממקור יווני. השם נפוץ בספרד ובאמריקה הלטינית. בארץ השם נדיר, והוא ניתן לבנות. מוכרות לו גם הצורות קטי וקטיה.", ["קטיה", "קטי"])
n("אביאלה", "אביאלה הוא הצורה הנשית של אביאל, שם עברי שפירושו אלוהים הוא אבי. השם ניתן לבנות, והוא נדיר. קרובים אליו השמות אביאל ואביה, והוא נשמע חגיגי ורך.", ["אביאל", "אביה"])
n("פלד", "פלד הוא שם עברי מהמילה פלדה, מתכת קשה וחזקה. השם נשמע חזק ויציב, והוא ניתן לבנים. הוא נדיר, ומוכר בארץ יותר כשם משפחה שבחרו אנשים בעברות שמם.", [])
n("שלהב", "שלהב הוא שם עברי מהמילה שלהבת, להבה של אש. השם נשמע חם ומלא אנרגיה. השם ניתן גם לבנים וגם לבנות, והוא נדיר. קרוב אליו השם שלהבת.", ["שלהבת"])
n("עוזיה", "עוזיה הוא שם עברי שפירושו ה׳ הוא העוז שלי. עוזיה היה מלך יהודה שמלך שנים רבות, ובימיו הממלכה הייתה חזקה. השם ניתן לבנים, והוא נדיר. קרובים אליו השמות עוזי ועוזיאל.", ["עוזי", "עוזיאל"])
n("מזלי", "מזלי הוא שם עברי שפירושו המזל שלי. השם היה נפוץ בעיקר בקהילות של יהודי צפון אפריקה ותימן. השם ניתן לבנות, והוא נדיר היום. קרוב אליו השם מזל.", ["מזל"])
n("ויקה", "ויקה היא צורת חיבה של ויקטוריה, שם לטיני שפירושו ניצחון. השם נפוץ בקרב דוברי רוסית, והוא הגיע לארץ עם העלייה. השם ניתן לבנות, והוא נדיר. קרוב אליו השם ויקי.", ["ויקי"])
n("אוליבייה", "אוליבייה הוא שם צרפתי שבא מהמילה הלטינית אוליבה, עץ זית. השם נפוץ מאוד בצרפת. בארץ הוא נדיר, והוא ניתן לבנים. קרובים אליו השמות אוליבר ואוליביה.", ["אוליביה", "אוליבר"])
n("אלקיים", "אלקיים הוא שם עברי שבנוי מהמילים אל וקיים, ופירושו אלוהים קיים. השם היה נפוץ בעיקר בקהילות של יהודי צפון אפריקה, ומוכר גם כשם משפחה. השם ניתן לבנים, והוא נדיר.", ["אליקים"])
n("פארן", "פארן הוא שמו של מדבר בדרום, בין סיני לנגב. בספר בראשית נאמר שישמעאל ישב במדבר פארן. היום נחל פארן הוא אחד הנחלים הגדולים בנגב, ופארן הוא גם יישוב בערבה. השם ניתן גם לבנים וגם לבנות.", [])
n("שבא", "שבא היא ממלכה עתיקה בדרום חצי האי ערב. בספר מלכים מלכת שבא באה לבקר את שלמה המלך, כדי לבחון את חוכמתו. השם ניתן לבנות, והוא נדיר. יש בו קסם של מסע ושל ארצות רחוקות.", [])
n("מישר", "מישר הוא שם עברי מהמילה מישור, וגם מהמילה יושר. השם מבטא דרך ישרה וכנה. השם ניתן גם לבנים וגם לבנות, והוא נדיר. הצליל שלו קצר ונקי.", [])
n("עמיטל", "עמיטל הוא שם עברי חדש שבנוי מהמילים עמי וטל, ופירושו העם שלי והטל. השם קרוב לשמות עמית וטל. השם ניתן גם לבנים וגם לבנות, והוא נדיר.", ["עמית", "טל"])
n("עדילי", "עדילי הוא שם עברי חדש, וכנראה הוא בא מהמילה עדי, תכשיט, ופירושו התכשיט שלי. השם קרוב לשמות עדי ועדיה. השם ניתן לבנות, והוא נדיר. הצליל שלו רך ומשחקי.", ["עדי"])
n("הילור", "הילור הוא שם עברי חדש, וכנראה הוא צירוף של המילים הילה ואור. השם נשמע בהיר וזוהר. השם ניתן לבנות, והוא נדיר. קרובים אליו השמות הילה ואור.", ["הילה", "אור"])
n("רקיע", "רקיע הוא שם עברי מהמילה רקיע, השמיים. בסיפור הבריאה הרקיע הוא מה שמפריד בין המים שלמעלה למים שלמטה. השם ניתן גם לבנים וגם לבנות, והוא נדיר. יש בו מרחב וכחול.", [])
n("נבון", "נבון הוא שם עברי מהמילה נבון, חכם ומבין. השם נשמע כמו ברכה לחוכמה. הוא מוכר בארץ גם כשם משפחה, כמו של יצחק נבון, נשיא המדינה החמישי. השם ניתן לבנים, והוא נדיר.", [])
n("תות", "תות הוא שם עברי של פרי, מתוק ואדום. השם נשמע קטן ומתוק, והוא ניתן לבנות. הוא נדיר, ושייך לקבוצה של שמות חדשים מעולם הפירות, כמו רימון ותאנה.", ["רימון", "תאנה"])
n("איבונה", "איבונה היא צורה של איבון, שם צרפתי ממקור גרמני שקשור לעץ הטקסוס. השם נפוץ בפולנית ובצ׳כית. בארץ השם נדיר, והוא ניתן לבנות.", ["איבון"])
